14:     .on('start', () => console.log(`# ${name}`))
15:     .on('complete', function(e) {
16:       const fastest = this.filter('fastest').map('name').toString();
17:       console.log(`fastest is '${fastest}'`);
18:       console.log();
19:     })
20: 
21:   const res = {
22:     run: suite.run.bind(suite),
23:     add(key, fn) {
24:       suite.add(key, {
25:         onCycle: e => cycle(e),
26:         onComplete: e => cycle(e, true),
27:         fn
28:       });
29:       return res;
30:     }
31:   };
32:   return res;
33: }
