57: function isNumberParseFloat(n) {
58:   if (typeof num === 'number') {
59:     return num - num === 0;
60:   }
61:   if (typeof num === 'string') {
62:     return (num - parseFloat(num)) > -1;
63:   }
64:   return false;
65: }
